import { useEffect, useState } from 'react';
import {defaultPreferences,readPreferences,type WorkbenchLayoutContext}from'@aork/contracts/workbench';
import type { ClientPluginContext, ViewProps } from '@aork/sdk/client';
function Layout({runtime}:ViewProps){const[preferences,setPreferences]=useState(defaultPreferences);const[hash,setHash]=useState(location.hash);const[layer,setLayer]=useState('visible');useEffect(()=>runtime.observeSnapshot('workbench.preferences',{}, {next:value=>setPreferences(readPreferences(value))},{owners:['workbench']}),[]);useEffect(()=>{const changed=()=>setHash(location.hash);addEventListener('hashchange',changed);return()=>removeEventListener('hashchange',changed);},[]);const context:WorkbenchLayoutContext={preferences,narrow:false,inspectorOverlay:false,save(update){const next={...preferences,...update};setPreferences(next);void runtime.command('workbench.savePreferences',next,crypto.randomUUID());}};const selected=new URLSearchParams(hash.slice(1));return <div style={{height:'100dvh',display:'grid',gridTemplateColumns:preferences.sidebarOpen?'280px minmax(0,1fr)':'minmax(0,1fr)',fontFamily:'var(--aork-font)',color:'var(--aork-text)',background:'var(--aork-surface)'}}>{preferences.sidebarOpen&&<aside aria-label="独立左栏"><strong>独立左栏</strong>{runtime.renderView('aork.workbench.sidebar@1',context)}</aside>}<section style={{overflow:'auto'}}><div style={{height:44,display:'flex',gap:12}}><strong>独立完整布局</strong>{runtime.renderView('aork.workbench.header-view@1',context)}</div><label>阅读区域可见性<select aria-label="阅读区域可见性" value={layer} onChange={event=>setLayer(event.target.value)}>{['visible','aria-hidden','visibility','opacity','inert','cover'].map(value=><option key={value} value={value}>{value}</option>)}</select></label><div style={{display:'flex',position:'relative'}}>{layer==='cover'&&<div aria-label="独立不透明覆盖层" style={{position:'absolute',inset:0,zIndex:2,background:'#ffffff',pointerEvents:'none'}}/>}<div style={{display:'flex',flexDirection:'column',minWidth:0,flex:1}}>{runtime.renderExtensions('aork.workbench.conversation@1',context)}<main data-aork-read-visibility={layer==='cover'?'covered':undefined} aria-hidden={layer==='aria-hidden'||undefined} inert={layer==='inert'||undefined} style={{minWidth:0,flex:1,visibility:layer==='visibility'?'hidden':'visible',opacity:layer==='opacity'?0:1}}>{runtime.renderView('aork.workbench.main@1',context)}</main></div>{selected.get('session')&&preferences.inspectorOpen&&<aside aria-label="独立右栏" style={{width:preferences.inspectorWide?520:360}}>{runtime.renderView('aork.workbench.inspector@1',context)}</aside>}</div></section></div>;}
function Messages({ runtime }: ViewProps) { const selected = new URLSearchParams(location.hash.slice(1)); const sessionId = selected.get('session'); const [value, setValue] = useState<any>(); useEffect(() => { if (!sessionId)
    return; return runtime.observeSnapshot('sessions.timeline', { sessionId }, { next: setValue }, { owners: ['sessions'] }); }, [sessionId]); if (selected.get('broken') === '1')
    throw Error('Controlled independent view failure'); return <section aria-label="独立消息"><h3>独立可替换消息</h3>{value?.turns.map((turn: any) => { const text = value.messages.filter((message: any) => message.turnId === turn.id && message.role === 'agent').map((message: any) => message.text).join(''); const reply = value.completedReplies.find((item: any) => item.turnId === turn.id); const content = <p>{text}</p>; return <article key={turn.id}>{reply ? runtime.renderView('aork.workbench.read-tracker@1', { sessionId, activityId: reply.activityId, content }) : content}</article>; })}</section>; }
function Inspector({ runtime }: ViewProps) { return <div aria-label="独立右侧栏容器"><strong>独立右侧栏容器</strong>{runtime.renderExtensions('aork.workbench.inspector-sections@1', { preferences: { inspectorWide: false } })}</div>; }
function Menu({ runtime }: ViewProps) { return <nav aria-label="独立菜单">{runtime.renderExtensions('aork.workbench.menu-items@1')}</nav>; }
function Notifications({ runtime }: ViewProps) { const [count, setCount] = useState<number>(); useEffect(() => runtime.observeSnapshot<any>('workbench.unread', {}, { next: value => setCount(value.count) }, { owners: ['workbench'] }), []); return <div aria-label="独立通知">独立未读 {count}{runtime.renderExtensions('aork.workbench.notification-sources@1')}</div>; }
export function activate(context: ClientPluginContext) {
  context.registerView('layout', Layout);
  context.registerView('messages', Messages);
  context.registerView('menu', Menu);
  context.registerView('right-region', Inspector);
  context.registerView('notifications', Notifications);
  context.registerExtension('alpha', () => <button>扩展 Alpha</button>);
  context.registerExtension('beta', () => <button>扩展 Beta</button>);
  context.registerExtension('notice', () => <span>扩展通知</span>);
  context.registerExtension('rail', () => <section aria-label="独立左栏分区"><h2>独立左栏分区</h2><p>由独立 UI 包贡献</p></section>);
  context.registerExtension('band', () => <div aria-label="独立中栏分区">独立中栏分区</div>);
  context.registerExtension('right-section', () => <section aria-label="独立右栏分区"><h2>独立右栏分区</h2><p>由独立 UI 包贡献</p></section>);
}
